CREATE TABLE `employee_target_mapping` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userid` int NOT NULL,
  `financial_year` varchar(10) NOT NULL,
  `target_amount` int NOT NULL,
  `incentive_amount` int NOT NULL,
  `status` int DEFAULT '237',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_mapping` (`userid`,`financial_year`,`target_amount`),
  KEY `employee_target_status_fk_idx` (`status`),
  CONSTRAINT `employee_target_mapping_ibfk_1` FOREIGN KEY (`userid`) REFERENCES `udnteam` (`userId`),
  CONSTRAINT `employee_target_status_fk` FOREIGN KEY (`status`) REFERENCES `udn_deal_status` (`id`)
