INSERT INTO `itinerary_master` VALUES (1,1668,'3 Days in Jaipur: The Pink City Experience','Explore the royal heritage of Jaipur through magnificent forts, colorful bazaars, historic palaces, and authentic Rajasthani cuisine.',NULL,NULL,NULL,_binary '\0'),(2,1668,'3 Days in Jaipur: The Pink City Experience (Copy)','Explore the royal heritage of Jaipur through magnificent forts, colorful bazaars, historic palaces, and authentic Rajasthani cuisine.',1,NULL,'2026-05-16 17:02:44',_binary '\0'),(3,1668,'3 Days in Jaipur: The Pink City Experience (Copy)','Explore the royal heritage of Jaipur through magnificent forts, colorful bazaars, historic palaces, and authentic Rajasthani cuisine.',1,NULL,'2026-05-16 17:03:09',_binary '\0'),(4,1683,'Gangtok Diaries','7Nights /8 Days',NULL,NULL,NULL,_binary '\0'),(5,1682,'Vietnam Diaries','9 Nights / 10 Days',NULL,NULL,NULL,_binary '\0'),(6,1682,'3 Nights/4 Days Darjeeling','',NULL,NULL,NULL,_binary '\0'),(7,1668,'5-Day Dummy Goa Itinerary','This 2-day Goa itinerary offers a perfect blend of relaxation, sightseeing, adventure, and cultural exploration. The trip covers the lively beaches of North Goa, the peaceful coastal charm of South Goa, historic forts and churches, local markets, water activities, and scenic attractions like Dudhsagar Waterfalls. Travelers can enjoy Goan cuisine, beachside experiences, nightlife, and leisure time while exploring the beauty and culture of Goa in a comfortable and enjoyable way.',NULL,NULL,NULL,_binary '\0'),(8,1686,'5N/6D Gangtok','',NULL,NULL,NULL,_binary '\0'),(9,1682,'9N/10D Vietnam ','2N in Hanoi \r\n\r\n2N in Da Nang \r\n\r\n3N in Phu Quoc\r\n\r\n2N in Ho Chi Minh',NULL,NULL,NULL,_binary '\0'),(10,1682,'9N/ 10D Vietnam  (Copy)','2N in Hanoi \r\n\r\n2N in Da Nang \r\n\r\n3N in Phu Quoc\r\n\r\n2N in Ho Chi Minh',9,NULL,'2026-05-21 10:38:06',_binary '\0'),(11,1687,'India Diaries','Delhi/Dharamshala/McLeod Ganj/Leh/Srinagar',NULL,NULL,NULL,_binary '\0'),(12,1687,'India Diaries','Delhi/Dharamshala/McLeod Ganj/Leh/Srinagar',NULL,NULL,NULL,_binary '\0'),(13,1694,'Kashmir Diaries','3N Srinagar',NULL,NULL,NULL,_binary '\0'),(14,1687,'Srinagar Diaries ','Leh/Srinagar',11,NULL,'2026-05-29 14:40:13',_binary '\0'),(15,1687,'Srinagar Diaries  (Copy)','Leh/Srinagar',14,NULL,'2026-05-29 14:58:19',_binary '\0'),(16,1533,'5 Nights Singapore','Singapore',NULL,NULL,NULL,_binary '\0'),(17,1687,'Kerala Diaries','Munnar: 2 Nights, Thekkady: 1 Nights, Alleppey: 1 Nights, Kovalam: 2 Nights, Kanyakumari: 1 Nights, Rameswaram: 2 Nights, Kodaikanal: 2 Nights',NULL,NULL,NULL,_binary '\0'),(18,1713,'1 N in Amritsar and 4 N in Dharmshala ','Amritsar Diaries ',NULL,NULL,NULL,_binary '\0'),(22,1714,'10N / 11D Europe Diaries ','Europe Diaries ',NULL,NULL,NULL,_binary '\0'),(23,1718,'4N/5D stay in Kashmir ','Kashmir Diaries ',NULL,NULL,NULL,_binary '\0'),(24,1719,'1N Nakuru, 3N Masai Mara','',NULL,NULL,NULL,_binary '\0'),(25,1724,'7N/8D Moscow Diaries ','Moscow Diaries ',NULL,NULL,NULL,_binary '\0'),(26,1725,'7N/8D Hyderabad Diaries ','Hyderabad Diaries ',NULL,NULL,NULL,_binary '\0'),(27,1725,'5N/6D Hyderabad Diaries  (Copy)','Hyderabad Diaries ',26,NULL,'2026-07-01 12:13:29',_binary '\0'),(28,1726,'4N/5D Kashmir Diaries ','5 Days stay in Kashmir ',NULL,NULL,NULL,_binary '\0'),(29,1728,'7N/8D In Madurai Diaries ','Madurai Diaries ',NULL,NULL,NULL,_binary '\0'),(30,1728,'5N/6D In Madurai Diaries  (Copy)','Madurai Diaries ',29,NULL,'2026-07-04 17:06:40',_binary '\0'),(31,1731,'3N Kuala Lumpur/ 2N Langkawi','Kuala Lumpur Diaries',NULL,NULL,NULL,_binary '\0'),(32,1731,'3N Kuala Lumpur/ 2N Langkawi/ 5N Bali','Malaysia + Indonesia Diaries',31,NULL,'2026-07-07 14:32:27',_binary '\0'),(33,1729,'2N Dwarka/2N Somnath','Somnath Diaries',NULL,NULL,NULL,_binary '\0'),(34,1730,'5N/6D Kashmir Diaries ','Kashmir Diaries ',NULL,NULL,NULL,_binary '\0'),(35,1732,'4N/5D Singapore Diaries ','Singapore Diaries ',NULL,NULL,NULL,_binary '\0'),(36,1733,'4N/5D Singapore','Singapore Diaries',NULL,NULL,NULL,_binary '\0'),(37,1735,'5N/6D Singapore','Singapore Diaries',NULL,NULL,NULL,_binary '\0'),(38,1735,'5N/6D Singapore','Singapore Diaries',NULL,NULL,NULL,_binary '\0'),(39,1737,'6N/7D Turkey Diaries ','Turkey Quotation ',NULL,NULL,NULL,_binary '\0'),(40,1728,'4N/5D In Madurai Diaries  ','Madurai Diaries ',30,NULL,'2026-07-15 17:55:42',_binary '\0'),(41,1736,'6N/7D Bali Diaries ','Bali Diaries  ',NULL,NULL,NULL,_binary '\0'),(42,1739,'6N/7D Japan  Diaries ','Japan Quotation ',NULL,NULL,NULL,_binary '\0'),(43,1738,'5N/6D Singapore and Malaysia Diaries ','Singapore and Malaysia Diaries ',NULL,NULL,NULL,_binary '\0'),(44,1740,'6N/7D Kerala Diaries ',' Kerala Diaries ',NULL,NULL,NULL,_binary '\0'),(45,1744,'5N/6D Srinagar Diaries ','Srinagar Diaries ',NULL,NULL,NULL,_binary '\0'),(46,1744,'5N/6D Kashmir  Quotation ','Kashmir  Quotation ',NULL,NULL,NULL,_binary '\0'),(47,1743,'10N New Zealand','Auckland (1N) / Rotorua (2N) / Christchurch (1N) / Greymouth (1N) / Franz Josef (1N) / Queenstown (3N) / Christchurch (1N)',NULL,NULL,NULL,_binary '\0');
