--
-- Table structure for table `tg_quotations_recorder`
--

DROP TABLE IF EXISTS `tg_quotations_recorder`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tg_quotations_recorder` (
  `quotationId` bigint NOT NULL AUTO_INCREMENT,
  `leadId` bigint DEFAULT NULL,
  `version` int DEFAULT NULL,
  `quotationName` varchar(245) DEFAULT NULL,
  `tourPackage` tinyint DEFAULT NULL,
  `flight` tinyint DEFAULT NULL,
  `hotel` tinyint DEFAULT NULL,
  `transfers` tinyint DEFAULT NULL,
  `sightseeing` tinyint DEFAULT NULL,
  `visa` tinyint DEFAULT NULL,
  `insurance` tinyint DEFAULT NULL,
  `cruise` tinyint DEFAULT NULL,
  `others` tinyint DEFAULT NULL,
  `converted` tinyint DEFAULT NULL,
  `lastUpdatedBy` int DEFAULT NULL,
  `createdBy` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `itineraryId` bigint DEFAULT NULL,
  PRIMARY KEY (`quotationId`),
  KEY `QTN_LEAD_KEY_idx` (`leadId`),
  KEY `QTN_CRTD-BY_idx` (`createdBy`),
  KEY `QTN_UPD_BY_idx` (`lastUpdatedBy`),
  CONSTRAINT `QTN_CRTD-BY` FOREIGN KEY (`createdBy`) REFERENCES `udnteam` (`userId`),
  CONSTRAINT `QTN_LEAD_KEY` FOREIGN KEY (`leadId`) REFERENCES `tg_leads_recorder` (`leadId`),
  CONSTRAINT `QTN_UPD_BY` FOREIGN KEY (`lastUpdatedBy`) REFERENCES `udnteam` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=2111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

