/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_ins_manual_quotation` (
  `manualInsuranceQuotationId` bigint NOT NULL AUTO_INCREMENT,
  `quotationId` bigint DEFAULT NULL,
  `insuranceName` varchar(300) DEFAULT NULL,
  `insuranceDetails` varchar(5000) DEFAULT NULL,
  `coverageStartDate` date DEFAULT NULL,
  `coverageEndDate` date DEFAULT NULL,
  `insuranceProvider` int DEFAULT NULL,
  `coverageAmount` int DEFAULT NULL,
  `coverageCurrency` varchar(10) DEFAULT NULL,
  `countryId` bigint DEFAULT NULL,
  `adults` int DEFAULT NULL,
  `children` int DEFAULT NULL,
  `insuranceType` int DEFAULT '0',
  `infant` int DEFAULT NULL,
  `premiumCost` int DEFAULT NULL,
  `premiumMarkup` int DEFAULT NULL,
  `remarks` varchar(3000) DEFAULT NULL,
  `displayOrder` int DEFAULT NULL,
  `active` tinyint DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`manualInsuranceQuotationId`),
  KEY `INS_QTNID_idx` (`quotationId`),
  CONSTRAINT `INS_QTNID` FOREIGN KEY (`quotationId`) REFERENCES `tg_quotations_recorder` (`quotationId`)
) ENGINE=InnoDB AUTO_INCREMENT=744 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
