--
-- Table structure for table `udn_ins_service_line`
--

DROP TABLE IF EXISTS `udn_ins_service_line`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_ins_service_line` (
  `insServiceId` bigint NOT NULL AUTO_INCREMENT,
  `dealConfirmationId` bigint DEFAULT NULL,
  `serviceMapId` bigint DEFAULT NULL,
  `applicantName` varchar(255) DEFAULT NULL,
  `coverageStartDate` date DEFAULT NULL,
  `coverageEndDate` date DEFAULT NULL,
  `destinationId` bigint DEFAULT NULL,
  `coverageAmount` int DEFAULT '0',
  `coverageCurrency` varchar(10) DEFAULT '0',
  `serviceLineCost` float DEFAULT '0',
  `markup` int DEFAULT NULL,
  `supplierId` bigint DEFAULT NULL,
  `remarks` varchar(245) DEFAULT NULL,
  `age` int DEFAULT NULL,
  `planName` varchar(145) DEFAULT NULL,
  `insuranceProvider` int DEFAULT '0',
  `insuranceType` int DEFAULT '0',
  `status` int DEFAULT '0',
  `displayOrder` int DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`insServiceId`),
  KEY `FK_INS_SERV_MAP_idx` (`serviceMapId`),
  KEY `FK_INS_DEST_idx` (`destinationId`),
  KEY `FK_INS_DEAL_CNF_idx` (`dealConfirmationId`),
  CONSTRAINT `FK_INS_DEAL_CNF` FOREIGN KEY (`dealConfirmationId`) REFERENCES `udn_deals_recorder` (`dealConfirmationId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_INS_DEST` FOREIGN KEY (`destinationId`) REFERENCES `udndestinations` (`destinationId`),
  CONSTRAINT `FK_INS_SERV_MAP` FOREIGN KEY (`serviceMapId`) REFERENCES `udn_deal_service_map` (`serviceMapId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_INS_SUPP` FOREIGN KEY (`insServiceId`) REFERENCES `tg_supplier_master` (`supplierId`)
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

