DROP TABLE IF EXISTS `udn_ldp_service_line`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_ldp_service_line` (
  `ldpServiceId` bigint NOT NULL AUTO_INCREMENT,
  `serviceMapId` bigint DEFAULT NULL,
  `dealConfirmationId` bigint DEFAULT NULL,
  `destinationId` bigint DEFAULT NULL,
  `adults` int DEFAULT NULL,
  `infants` int DEFAULT '0',
  `children` int DEFAULT NULL,
  `startdate` date DEFAULT NULL,
  `enddate` date DEFAULT NULL,
  `holdingDate` date DEFAULT NULL,
  `packageName` varchar(500) DEFAULT NULL,
  `packageType` varchar(10) DEFAULT NULL,
  `packageDetails` text,
  `serviceLineCost` float DEFAULT NULL,
  `serviceLineMarkup` float DEFAULT '0',
  `inclusions` varchar(3000) DEFAULT NULL,
  `exclusions` varchar(3000) DEFAULT NULL,
  `cancellationPolicy` varchar(3000) DEFAULT NULL,
  `supplierId` bigint DEFAULT NULL,
  `remarks` varchar(5000) DEFAULT NULL,
  `status` int DEFAULT NULL,
  `displayOrder` int DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
