DROP TABLE IF EXISTS `udn_sight_seeing_master`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_sight_seeing_master` (
  `sightSeeingId` bigint NOT NULL AUTO_INCREMENT,
  `sightSeeingName` varchar(250) NOT NULL,
  `cityId` bigint DEFAULT NULL,
  `sightSeeingDescription` varchar(3000) DEFAULT NULL,
  `duration` int DEFAULT NULL,
  `departurePoint` varchar(145) DEFAULT NULL,
  `reportingPoint` varchar(145) DEFAULT NULL,
  `meals` varchar(45) DEFAULT NULL,
  `usefulInfo` varchar(3000) DEFAULT NULL,
  `tnc` varchar(2000) DEFAULT NULL,
  `standardPickupTime` varchar(45) DEFAULT NULL,
  `standardDropTime` varchar(45) DEFAULT NULL,
  `tourRating` int DEFAULT NULL,
  `flexibleTimming` tinyint DEFAULT NULL,
  `active` tinyint DEFAULT NULL,
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`sightSeeingId`),
  KEY `SS_CITY_FK_idx` (`cityId`),
  CONSTRAINT `SS_CITY_FK` FOREIGN KEY (`cityId`) REFERENCES `udndestinations` (`destinationId`)
) ENGINE=InnoDB AUTO_INCREMENT=17017 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
