--
-- Table structure for table `udn_task_recorder`
--

DROP TABLE IF EXISTS `udn_task_recorder`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_task_recorder` (
  `taskId` bigint NOT NULL AUTO_INCREMENT,
  `taskTitle` varchar(145) DEFAULT NULL,
  `taskDescription` varchar(1200) DEFAULT NULL,
  `taskPriority` varchar(45) DEFAULT NULL,
  `dealConfirmationId` bigint DEFAULT NULL,
  `taskOwner` int DEFAULT NULL,
  `taskCreator` int DEFAULT NULL,
  `taskDueDate` datetime DEFAULT NULL,
  `taskStatus` varchar(45) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`taskId`),
  KEY `FK_OWNER_idx` (`taskOwner`),
  KEY `FK_CREATOR_idx` (`taskCreator`),
  CONSTRAINT `FK_CREATOR` FOREIGN KEY (`taskCreator`) REFERENCES `udnteam` (`userId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_OWNER` FOREIGN KEY (`taskOwner`) REFERENCES `udnteam` (`userId`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=354 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

