--
-- Table structure for table `udn_vsa_service_line`
--

DROP TABLE IF EXISTS `udn_vsa_service_line`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_vsa_service_line` (
  `vsaServiceId` bigint NOT NULL AUTO_INCREMENT,
  `visaId` int DEFAULT NULL,
  `dealConfirmationId` bigint DEFAULT NULL,
  `serviceMapId` bigint DEFAULT NULL,
  `countryCode` varchar(45) DEFAULT NULL,
  `applicantName` varchar(145) DEFAULT NULL,
  `travelStartDate` date DEFAULT NULL,
  `travelReturnDate` date DEFAULT NULL,
  `passportNumber` varchar(45) DEFAULT NULL,
  `passportExpiryDate` date DEFAULT NULL,
  `remarks` varchar(2000) DEFAULT NULL,
  `supplierId` bigint DEFAULT NULL,
  `status` int DEFAULT NULL,
  `serviceLineCost` float DEFAULT NULL,
  `markup` float DEFAULT NULL,
  `displayOrder` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`vsaServiceId`),
  KEY `FK_VSA_STATUS_idx` (`status`),
  KEY `FK_VSA_SRV_MAP_idx` (`serviceMapId`),
  KEY `FK_VSA_DEAL_CNF_idx` (`dealConfirmationId`),
  KEY `FK_VSA_ID_idx` (`visaId`),
  KEY `FK_Supplier_ID_idx` (`supplierId`),
  CONSTRAINT `FK_Supplier_ID` FOREIGN KEY (`supplierId`) REFERENCES `tg_supplier_master` (`supplierId`),
  CONSTRAINT `FK_VSA_DEAL_CNF` FOREIGN KEY (`dealConfirmationId`) REFERENCES `udn_deals_recorder` (`dealConfirmationId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_VSA_ID` FOREIGN KEY (`visaId`) REFERENCES `udn_visa_master` (`visaId`),
  CONSTRAINT `FK_VSA_SRV_MAP` FOREIGN KEY (`serviceMapId`) REFERENCES `udn_deal_service_map` (`serviceMapId`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

