DROP TABLE IF EXISTS `udnclients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udnclients` (
  `clientId` bigint NOT NULL AUTO_INCREMENT,
  `address` varchar(255) DEFAULT NULL,
  `cityId` bigint DEFAULT NULL,
  `clientName` varchar(255) NOT NULL,
  `email` varchar(255) DEFAULT NULL,
  `bankDetails` varchar(255) DEFAULT NULL,
  `companyDetails` varchar(255) DEFAULT NULL,
  `gstDetails` varchar(255) DEFAULT NULL,
  `mobile` bigint DEFAULT NULL,
  `phone` bigint DEFAULT NULL,
  `referredBy` varchar(255) DEFAULT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  `countryId` bigint DEFAULT NULL,
  `passportNumber` varchar(45) DEFAULT NULL,
  `passportExpiry` date DEFAULT NULL,
  `birthDate` date DEFAULT NULL,
  `anniversaryDate` date DEFAULT NULL,
  `hotelPref` int DEFAULT NULL,
  `costSavvy` int DEFAULT NULL,
  `serviceSavvy` int DEFAULT NULL,
  `foodPref` varchar(45) DEFAULT NULL,
  `aggressiveness` int DEFAULT NULL,
  `paymentRating` int DEFAULT NULL,
  `active` tinyint DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`clientId`),
  KEY `FK_CLT_CITY_idx` (`cityId`),
  CONSTRAINT `FK_CLT_CITY` FOREIGN KEY (`cityId`) REFERENCES `udndestinations` (`destinationId`)
) ENGINE=InnoDB AUTO_INCREMENT=23987 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

