  `ApprovedAmount` int DEFAULT NULL,
  `UserRemarks` varchar(300) DEFAULT NULL,
  `ManagementRemarks` varchar(500) DEFAULT NULL,
  `responseDate` datetime DEFAULT NULL,
  `Status` int NOT NULL,
  `claimOption` enum('INCENTIVE','TARGET') NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` varchar(45) DEFAULT NULL,
  `verified` tinyint DEFAULT '0',
  PRIMARY KEY (`IncentiveId`),
  KEY `FK_USRNAME_idx` (`claimantId`),
  KEY `FK_DEAL_CNF_idx` (`dealConfirmationId`),
